const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const states = ee.FeatureCollection('TIGER/2018/States');
    const wa = states.filter(ee.Filter.eq('NAME', 'Washington')).geometry();
    const date1Str = '2021-11-15';
    const date2Str = '2021-11-22';

    // Helper to await getInfo
    function getInfoAsync(obj) {
      return new Promise((resolve, reject) => {
        obj.getInfo(resolve, reject);
      });
    }

    // 2. Data Acquisition & Check with fallback
    async function fetchDailyImage(dateStr) {
      const date = ee.Date(dateStr);
      // Try ERA5-Land
      let col = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
        .filterDate(date, date.advance(1, 'day'))
        .select(['volumetric_soil_water_layer_1'], ['sm'])
        .filterBounds(wa);
      let size = await getInfoAsync(col.size());
      if (size > 0) {
        return { img: ee.Image(col.first()), source: 'ERA5-Land', imgCount: size };
      }
      // Fallback: SMAP HSL (gap-filled)
      col = ee.ImageCollection('NASA_USDA/HSL/SMAP10KM_soil_moisture')
        .filterDate(date, date.advance(1, 'day'))
        .select(['ssm'], ['sm'])
        .filterBounds(wa);
      size = await getInfoAsync(col.size());
      if (size > 0) {
        return { img: ee.Image(col.first()), source: 'SMAP-HSL', imgCount: size };
      }
      return null;
    }

    async function computeStats(img, label) {
      const mean = ee.Number(img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: wa,
        scale: 9000,
        maxPixels: 1e9
      }).get('sm'));
      const count = ee.Number(img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: wa,
        scale: 9000,
        maxPixels: 1e9
      }).get('sm'));
      const meanVal = await getInfoAsync(mean);
      const countVal = await getInfoAsync(count);
      return { mean: meanVal, count: countVal };
    }

    console.log('Region: Washington, USA');
    console.log(`Dates: ${date1Str} vs ${date2Str}`);

    const rec1 = await fetchDailyImage(date1Str);
    const rec2 = await fetchDailyImage(date2Str);

    if (!rec1 || !rec2) {
      if (!rec1) console.log(`${date1Str} Images: 0`);
      if (!rec2) console.log(`${date2Str} Images: 0`);
      console.log('C1');
      return;
    }

    console.log(`${date1Str} Source: ${rec1.source}, Images: ${rec1.imgCount}`);
    console.log(`${date2Str} Source: ${rec2.source}, Images: ${rec2.imgCount}`);

    // 3. Processing & pixel validation
    const stats1 = await computeStats(rec1.img, date1Str);
    const stats2 = await computeStats(rec2.img, date2Str);

    if (!stats1.count || !stats2.count || stats1.count === 0 || stats2.count === 0) {
      console.log('No valid pixels after masking.');
      console.log('C2');
      return;
    }

    // 4. Calculation & validation
    const v1 = stats1.mean;
    const v2 = stats2.mean;

    console.log(`${date1Str} Pixels: ${stats1.count}, Mean SM: ${v1 !== null ? v1.toFixed(4) : 'null'} m3/m3`);
    console.log(`${date2Str} Pixels: ${stats2.count}, Mean SM: ${v2 !== null ? v2.toFixed(4) : 'null'} m3/m3`);

    if (v1 === null || v2 === null || isNaN(v1) || isNaN(v2) || v1 < 0 || v2 < 0 || v1 > 1.2 || v2 > 1.2) {
      console.log('C3');
      return;
    }

    const diff = v2 - v1;
    console.log(`Difference (22-15): ${diff.toFixed(4)} m3/m3`);

    // 5. Final Answer
    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.error('Error:', err.toString().slice(0, 200));
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
